#!/usr/bin/env python3
import cadquery as cq
from pathlib import Path

SPEC = {'kind': 'extrusion', 'center': [0.0005719200000000035, -0.107112335, 0.026705265000000006], 'basis': [[0.0, 0.8084858267879974, 0.5885156479507817], [-0.9999999999521855, 5.7551054810034746e-06, -7.906197956269736e-06], [-9.779018622602166e-06, -0.5885156479226421, 0.80848582674934]], 'axis': [0.5885156479507817, -7.906197956269736e-06, 0.80848582674934], 'zmin': -0.3211915210881249, 'zmax': 0.3211960492093674, 'profiles': [{'outer': [[-0.2776988660686971, 0.05024682861901499], [-0.2737411147500146, 0.06265425041121431], [-0.268950103814905, 0.07500688509493454], [-0.2633259240300435, 0.08716349085609147], [-0.25686855462885266, 0.09923360289474732], [-0.24950850599428226, 0.11116245763922232], [-0.24138473851024989, 0.1229269831043415], [-0.23242773217646553, 0.13446377891722613], [-0.22270701699312148, 0.14580453443698416], [-0.21215305295992765, 0.15694927500373315], [-0.20083534046060936, 0.167811481950317], [-0.1888232894952612, 0.178422866690026], [-0.1760474596800599, 0.1888065361472648], [-0.16257731216540594, 0.1988298401127082], [-0.14841281618462426, 0.20857065128168212], [-0.13355401173771483, 0.21802892923012537], [-0.11807032959115384, 0.227126861941579], [-0.10196169936209268, 0.2358557890739879], [-0.08529763105013692, 0.24424741912756726], [-0.06800862503882295, 0.2522470259833651], [-0.05023361132814414, 0.2598545457620723], [-0.03190314991810381, 0.267070002318629], [-0.01308664080860085, 0.2738617092931859], [0.006146465616737149, 0.2802382722609772], [0.0258656201249731, 0.2861824606160554], [0.04600133156551101, 0.2916883991263119], [0.06641482070552149, 0.2967389046936326], [0.08724486716156261, 0.301342561125746], [0.1083526709335432, 0.30546770303132714], [0.1296687720213688, 0.30914596906022984], [0.1513320400416952, 0.3122909356504567], [0.17313415576150093, 0.3150121627417147], [0.1951445784137163, 0.3172317456132714], [0.21722441838207668, 0.3189728188427693], [0.23944312528285003, 0.3201805717775069], [0.2617312798830082, 0.3209328628285386], [0.2840888610322452, 0.3211921656295827], [0.2840851689405879, -0.3211954597856317], [0.26172759009196284, -0.32093585113497564], [0.23943944431101266, -0.3202064159800272], [0.21722075159744395, -0.3189752933802206], [0.1951409315676224, -0.31723400791726564], [0.17313053422164926, -0.3150141489324246], [0.15132844994353978, -0.31229271131868747], [0.12966521796642685, -0.3091474093600927], [0.1083491590559975, -0.3054689398886567], [0.08724140282980104, -0.30134358296810426], [0.06641140928812747, -0.2967396448680221], [0.04599797843038346, -0.29168890285171745], [0.025862329872846892, -0.2861827002361032], [0.006143244382675206, -0.2802383025652632], [-0.013089789189951956, -0.2738615226201824], [-0.03190622007855181, -0.2670695931789297], [-0.05023659866695414, -0.2598539454905431], [-0.0680115249548689, -0.252246214519076], [-0.08530043894180381, -0.24424643511797775], [-0.10196441062825445, -0.235854621342871], [-0.11807294039735952, -0.22712547497212202], [-0.13355651824980677, -0.21802739346660305], [-0.14841521380128087, -0.20856891655078313], [-0.16257959781924242, -0.19882794823127314], [-0.17604963030310475, -0.1888044855367975], [-0.1888253404869751, -0.17842069476807848], [-0.20083726952018482, -0.1678091460275028], [-0.21215485701978426, -0.15694679264266334], [-0.22270869298558119, -0.14580195485287364], [-0.23242927780130754, -0.13446106319180867], [-0.24138615146666664, -0.12292419662208812], [-0.24950978398185747, -0.11115957765146814], [-0.25686969534658327, -0.09923063010721242], [-0.2633269259447749, -0.0871604437436713], [-0.26895096615937547, -0.07500377324782183], [-0.27374183522371, -0.06265107753421499], [-0.27769944390474677, -0.050243624158298694], [-0.28075441181876043, -0.03772661135121105], [-0.2829067797330129, -0.02517791477972621], [-0.2840870151781342, 5.9515085228975025e-06], [-0.282906490239933, 0.02518118726449415], [-0.28075397815439124, 0.03772985906094051]], 'holes': []}], 'simplify_tolerance': 0.00012847752508304288, 'sketch_entity_count': 88}
OUT = Path(__file__).resolve().parent

def vec(v):
    return cq.Vector(float(v[0]), float(v[1]), float(v[2]))

def build():
    s = SPEC
    kind = s["kind"]
    B = s.get("basis")
    center = s.get("center")
    if kind == "extrusion":
        xdir = [B[i][0] for i in range(3)]
        axis = [B[i][2] for i in range(3)]
        origin = [center[i] + s["zmin"] * axis[i] for i in range(3)]
        plane = cq.Plane(origin=origin, xDir=xdir, normal=axis)
        result = None
        height = s["zmax"] - s["zmin"]
        for profile in s["profiles"]:
            solid = cq.Workplane(plane).polyline(profile["outer"]).close().extrude(height)
            for hole in profile["holes"]:
                cutter = cq.Workplane(plane).polyline(hole).close().extrude(height)
                solid = solid.cut(cutter)
            result = solid if result is None else result.union(solid)
    elif kind == "multi_loft":
        def loft(track):
            wires = [cq.Wire.makePolygon([vec(p) for p in section], close=True) for section in track]
            return cq.Solid.makeLoft(wires, ruled=bool(s.get("ruled", True)))
        outer = [loft(track) for track in s["outer_tracks"]]
        # Keep disjoint solids as a legal STEP compound.  Global Boolean fusion
        # is unnecessary for training geometry and scales poorly with profiles.
        for track in s.get("hole_tracks", []):
            cutter = loft(track)
            cut_outer = []
            for solid in outer:
                try:
                    cut_outer.append(solid.cut(cutter))
                except Exception:
                    cut_outer.append(solid)
            outer = cut_outer
        result = outer[0] if len(outer) == 1 else cq.Compound.makeCompound(outer)
    elif kind == "box":
        xdir = [B[i][0] for i in range(3)]
        axis = [B[i][2] for i in range(3)]
        origin = [center[i] + s["mins"][0]*B[i][0] + s["mins"][1]*B[i][1] + s["mins"][2]*B[i][2] for i in range(3)]
        plane = cq.Plane(origin=origin, xDir=xdir, normal=axis)
        dx=s["maxs"][0]-s["mins"][0]; dy=s["maxs"][1]-s["mins"][1]; dz=s["maxs"][2]-s["mins"][2]
        result = cq.Workplane(plane).rect(dx,dy,centered=False).extrude(dz)
    elif kind == "cylinder":
        xdir = [B[i][0] for i in range(3)]
        axis = [B[i][2] for i in range(3)]
        origin = [center[i] + s["zmin"] * axis[i] for i in range(3)]
        plane = cq.Plane(origin=origin, xDir=xdir, normal=axis)
        result = cq.Workplane(plane).circle(s["radius"]).extrude(s["zmax"]-s["zmin"])
    else:
        raise ValueError(kind)
    cq.exporters.export(result, str(OUT / "reconstructed.step"))
    cq.exporters.export(result, str(OUT / "reconstructed.stl"), tolerance=0.001, angularTolerance=0.05)
    return result

if __name__ == "__main__":
    build()
